  ["seq 1 3", "", "1\n2\n3\n"],
  ["nl -ba -w1 -s: -", "a\n\nb\n", "1:a\n2:\n3:b\n"],
  ["rev", "abc\n", "cba\n"],
  ["unexpand -a", "        x\n", "\tx\n"],
  ["tac", "a\nb\n", "b\na\n"],
