import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { FsError, Shell, standardCommands, createMemoryFileSystem, createMountFileSystem } from "virtual-bash";
import type { ErrnoCode, WebDavAtomicEmptyDirectoryBinding as RootBinding } from "virtual-bash";
import { WebDavFileSystem } from "virtual-bash/fs/webdav";
import type { WebDavAtomicEmptyDirectoryBinding, WebDavAtomicEmptyDirectoryRequest, WebDavAtomicEmptyDirectoryResult, WebDavFetch } from "virtual-bash/fs/webdav";
import { createHttpsFetch, type WireObservation } from "./https.mjs";

export interface LiteralConfiguration {
  readonly namespaceUrl: string;
  readonly stockUrl: string;
  readonly caFile: string;
  readonly authorization: string;
  readonly serverRoot: string;
  readonly controlRoot: string;
}

export const operation = "atomic-empty-rmdir/v1";

function responseError(response: Response, path: string): FsError {
  const native = response.headers.get("X-Atomic-Error");
  const nativeStatuses: Record<string, number> = { ENOTEMPTY: 409, ENOTDIR: 409, ENOENT: 404, EACCES: 403, EBUSY: 409, ENOTSUP: 409, EINVAL: 400, EIO: 500, ETIMEDOUT: 500 };
  const statusCodes: Record<number, ErrnoCode> = { 400: "EINVAL", 401: "EACCES", 403: "EACCES", 404: "ENOENT", 405: "ENOTSUP", 409: "EAGAIN", 412: "EAGAIN", 423: "EBUSY", 501: "ENOTSUP" };
  const code = native && nativeStatuses[native] === response.status ? native as ErrnoCode : statusCodes[response.status] ?? "EIO";
  return new FsError(code, { syscall: "rmdir", path, message: `atomic provider HTTP ${response.status}; no retry` });
}

export function createAtomicBinding(namespaceUrl: string, fetch: WebDavFetch, authorization: string): WebDavAtomicEmptyDirectoryBinding {
  const base = new URL(namespaceUrl);
  if (base.protocol !== "https:" || base.hostname !== "127.0.0.1" || base.username || base.password
    || base.search || base.hash || !base.pathname.endsWith("/") || base.href !== namespaceUrl) throw new Error("explicit canonical loopback HTTPS namespace required");
  const binding: RootBinding = Object.freeze({
    namespaceUrl,
    async removeEmptyDirectory(input: WebDavAtomicEmptyDirectoryRequest): Promise<WebDavAtomicEmptyDirectoryResult> {
      if (input.namespaceUrl !== namespaceUrl || input.operation !== operation) throw new FsError("EINVAL", { syscall: "rmdir", path: input.path });
      input.signal?.throwIfAborted();
      const parts = input.path.slice(1).split("/");
      if (!input.path.startsWith("/") || input.path === "/" || input.path.includes("\\") || input.path.includes("\0")
        || parts.some((part) => !part || part === "." || part === "..")) throw new FsError("EINVAL", { syscall: "rmdir", path: input.path });
      const headers = { Authorization: authorization, "X-Atomic-Namespace": namespaceUrl };
      const settings = { redirect: "manual", credentials: "omit", ...(input.signal ? { signal: input.signal } : {}) } as const;
      const probe = await fetch(namespaceUrl, { ...settings, method: "OPTIONS", headers: { ...headers, "X-Atomic-Empty-Probe": operation } });
      try {
        if (probe.status !== 200 || probe.headers.get("X-Atomic-Capability") !== operation || probe.headers.get("X-Atomic-Namespace") !== namespaceUrl) {
          if (probe.status === 401 || probe.status === 403) throw responseError(probe, input.path);
          throw new FsError("ENOTSUP", { syscall: "rmdir", path: input.path, message: "server did not confirm bound atomic extension; no DELETE issued" });
        }
      } finally { await probe.body?.cancel(); }
      input.signal?.throwIfAborted();
      const url = `${namespaceUrl}${parts.map(encodeURIComponent).join("/")}/`;
      const response = await fetch(url, { ...settings, method: "DELETE", headers: { ...headers, Depth: "infinity",
        "X-Atomic-Empty-Directory": operation, "X-Atomic-Path": Buffer.from(input.path).toString("base64url") } });
      try {
        if (response.status !== 204) throw responseError(response, input.path);
        const encoded = response.headers.get("X-Atomic-Receipt");
        if (!encoded || encoded.length > 4096 || !/^[A-Za-z0-9_-]+$/u.test(encoded)) throw new FsError("EIO", { message: "missing atomic receipt; outcome uncertain" });
        const receipt: unknown = JSON.parse(Buffer.from(encoded, "base64url").toString("utf8"));
        if (!receipt || typeof receipt !== "object" || !("operation" in receipt) || receipt.operation !== operation
          || !("namespaceUrl" in receipt) || receipt.namespaceUrl !== namespaceUrl || !("path" in receipt) || receipt.path !== input.path
          || !("outcome" in receipt) || receipt.outcome !== "removed") throw new FsError("EIO", { message: "mismatched atomic receipt; outcome uncertain" });
        return { operation, namespaceUrl, path: input.path, outcome: "removed" };
      } finally { await response.body?.cancel(); }
    },
  });
  return binding;
}

export async function createApplication(config: LiteralConfiguration, events: WireObservation[] = []) {
  const fetch = createHttpsFetch(new URL(config.namespaceUrl).origin, await readFile(config.caFile), events);
  const common = { fetch, headers: { Authorization: config.authorization }, timeoutMs: 5000 };
  const dav = new WebDavFileSystem({ ...common, baseUrl: config.namespaceUrl,
    atomicEmptyDirectory: createAtomicBinding(config.namespaceUrl, fetch, config.authorization) });
  const stock = new WebDavFileSystem({ ...common, baseUrl: config.stockUrl });
  const mounted = createMountFileSystem({ root: createMemoryFileSystem(), mounts: { "/dav": dav, "/stock": stock } });
  const shell = new Shell({ fs: mounted }).use(standardCommands());
  return { dav, stock, fetch, mounted, shell };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (!process.argv[2]) throw new Error("literal configuration JSON path required");
  const config: LiteralConfiguration = JSON.parse(await readFile(process.argv[2], "utf8"));
  const { shell } = await createApplication(config);
  const result = await shell.exec("mkdir /dav/public-example-empty && rmdir /dav/public-example-empty && printf 'atomic cleanup complete\\n'");
  process.stdout.write(JSON.stringify(result));
  if (result.exitCode !== 0 || result.stdout !== "atomic cleanup complete\n") process.exitCode = 1;
}

import { request } from "node:https";
import { once } from "node:events";
import type { IncomingMessage } from "node:http";
import type { WebDavFetch } from "virtual-bash/fs/webdav";

export interface WireObservation {
  readonly url: string;
  readonly method: string;
  readonly requestHeaders: Readonly<Record<string, string>>;
  status?: number;
  responseHeaders?: Record<string, string>;
  uploadedBytes: number;
  downloadedBytes: number;
  pulls: number;
  drains: number;
  aborted: boolean;
  cancelled: boolean;
  ended: boolean;
}

export function createHttpsFetch(origin: string, certificate: Uint8Array, events: WireObservation[] = []): WebDavFetch {
  const allowed = new URL(origin);
  if (allowed.protocol !== "https:" || allowed.hostname !== "127.0.0.1" || allowed.username || allowed.password) {
    throw new Error("fixture transport requires explicit numeric loopback HTTPS");
  }
  const ca = Buffer.from(certificate);
  return async (url, init) => {
    const target = new URL(url);
    if (target.origin !== allowed.origin || target.username || target.password) throw new Error("unconfigured HTTPS origin");
    if (init.redirect !== "manual" || init.credentials !== "omit") throw new Error("explicit manual/omit policy required");
    const normalized = new Request(url, init);
    const requestHeaders = new Headers(normalized.headers);
    const originalBody = init.body;
    const knownLength = typeof originalBody === "string" ? Buffer.byteLength(originalBody)
      : ArrayBuffer.isView(originalBody) ? originalBody.byteLength
      : originalBody instanceof ArrayBuffer ? originalBody.byteLength
      : originalBody instanceof Blob ? originalBody.size
      : originalBody instanceof URLSearchParams ? Buffer.byteLength(originalBody.toString()) : undefined;
    if (knownLength !== undefined && !requestHeaders.has("content-length")) requestHeaders.set("content-length", String(knownLength));
    const signal = AbortSignal.any([normalized.signal, AbortSignal.timeout(10000)]);
    signal.throwIfAborted();
    const event: WireObservation = {
      url, method: normalized.method, requestHeaders: Object.fromEntries(requestHeaders),
      uploadedBytes: 0, downloadedBytes: 0, pulls: 0, drains: 0,
      aborted: false, cancelled: false, ended: false,
    };
    events.push(event);
    return new Promise<Response>((resolve, reject) => {
      let incoming: IncomingMessage | undefined;
      let bodyController: ReadableStreamDefaultController<Uint8Array> | undefined;
      const upload = normalized.body?.getReader();
      let finished = false;
      const cleanup = () => signal.removeEventListener("abort", abort);
      const fail = (reason: unknown) => {
        if (finished) return;
        finished = true;
        cleanup();
        reject(reason);
        bodyController?.error(reason);
        incoming?.destroy();
        outgoing.destroy(reason instanceof Error ? reason : new Error(String(reason)));
        void upload?.cancel(reason).catch(() => {});
      };
      const abort = () => { event.aborted = true; fail(signal.reason); };
      const outgoing = request(target, {
        method: normalized.method, headers: Object.fromEntries(requestHeaders),
        ca, rejectUnauthorized: true, agent: false,
      }, response => {
        incoming = response;
        const headers = new Headers();
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
          headers.append(response.rawHeaders[index]!, response.rawHeaders[index + 1]!);
        }
        event.status = response.statusCode!;
        event.responseHeaders = Object.fromEntries(headers);
        response.on("error", fail);
        const iterator = response[Symbol.asyncIterator]();
        const noBody = normalized.method === "HEAD" || [204, 205, 304].includes(response.statusCode!);
        const body = noBody ? null : new ReadableStream<Uint8Array>({
          start(controller) { bodyController = controller; },
          async pull(controller) {
            try {
              signal.throwIfAborted();
              event.pulls++;
              const item = await iterator.next();
              signal.throwIfAborted();
              if (item.done) {
                event.ended = true;
                finished = true;
                cleanup();
                controller.close();
              } else {
                const bytes = new Uint8Array(item.value as Uint8Array);
                event.downloadedBytes += bytes.byteLength;
                controller.enqueue(bytes);
              }
            } catch (error) { fail(error); }
          },
          cancel(reason) {
            event.cancelled = true;
            finished = true;
            cleanup();
            response.destroy();
            outgoing.destroy();
            void upload?.cancel(reason).catch(() => {});
            void iterator.return?.().catch(() => {});
          },
        }, { highWaterMark: 0 });
        if (noBody) {
          response.once("end", () => { event.ended = true; finished = true; cleanup(); });
          response.resume();
        }
        const result = new Response(body, { status: response.statusCode!, statusText: response.statusMessage ?? "", headers });
        Object.defineProperty(result, "url", { value: target.href });
        resolve(result);
      });
      outgoing.on("error", fail);
      signal.addEventListener("abort", abort, { once: true });
      if (signal.aborted) { abort(); return; }
      void (async () => {
        try {
          if (upload) {
            while (true) {
              signal.throwIfAborted();
              const item = await upload.read();
              if (item.done) break;
              const bytes = Buffer.from(item.value);
              event.uploadedBytes += bytes.length;
              if (!outgoing.write(bytes)) {
                event.drains++;
                await once(outgoing, "drain", { signal });
              }
            }
          }
          outgoing.end();
        } catch (error) { fail(error); }
        finally { upload?.releaseLock(); }
      })();
    });
  };
}

import assert from "node:assert/strict";
import { readFile, writeFile, stat as hostStat } from "node:fs/promises";
import { createHash } from "node:crypto";
import { setTimeout as delay } from "node:timers/promises";
import { FsError, WebDavFileSystem as RootWebDav, readBytes } from "virtual-bash";
import { WebDavFileSystem } from "virtual-bash/fs/webdav";
import type { WebDavFetch, WebDavFileSystemOptions } from "virtual-bash/fs/webdav";
import { createApplication, type LiteralConfiguration } from "./example.mjs";
import type { WireObservation } from "./https.mjs";

const config: LiteralConfiguration = JSON.parse(await readFile(process.argv[2]!, "utf8"));
const evidence = process.argv[3]!;
const provider = process.argv[4]!;
const events: WireObservation[] = [];
const app = await createApplication(config, events);
const settings: WebDavFileSystemOptions = { baseUrl: config.baseUrl, fetch: app.fetch, headers: { Authorization: config.authorization }, timeoutMs: 2000 };
const payload = new Uint8Array([0, 255, 128, 195, 169, 13, 10, 0, 65]);
const old = new Uint8Array([79, 76, 68]);
const rows: object[] = [];
const observations: object[] = [];
let paths: string[] = [];
let sequence = 0;
const url = (path: string) => new URL(path.slice(1), config.baseUrl).href;
const hash = (bytes: Uint8Array) => createHash("sha256").update(bytes).digest("hex");
const isCode = (code: string) => (error: unknown) => error instanceof FsError && error.code === code;
async function wire(path: string, init: RequestInit): Promise<Response> {
  const headers = new Headers(init.headers); headers.set("Authorization", config.authorization);
  return app.fetch(url(path), { ...init, headers, redirect: "manual", credentials: "omit" });
}
async function seed() {
  const source = `/ind-${++sequence}-source`, target = `/ind-${sequence}-target`;
  paths.push(source, target);
  await app.native.writeFile(source, payload); await app.native.writeFile(target, old);
  return { source, target };
}
async function unchanged(source: string, target: string) {
  assert.deepEqual(await app.native.readFile(source), payload);
  assert.deepEqual(await app.native.readFile(target), old);
}
async function discovery(path: string) {
  const response = await wire(path, { method: "PROPFIND", headers: { Depth: "0", "Content-Type": "application/xml" }, body: '<d:propfind xmlns:d="DAV:"><d:prop><d:lockdiscovery/></d:prop></d:propfind>' });
  const body = await response.text();
  observations.push({ kind: "lockdiscovery", path, status: response.status, body });
  return body;
}
async function witnesses() {
  const result: Record<string, unknown> = {};
  for (const path of paths) {
    try {
      const metadata = await hostStat(`${config.serverRoot}${path}`);
      const bytes = await readFile(`${config.serverRoot}${path}`);
      result[path] = { dev: metadata.dev, ino: metadata.ino, nlink: metadata.nlink, bytes: bytes.length <= 64 ? [...bytes] : undefined, size: bytes.length, sha256: hash(bytes) };
    } catch (error) { result[path] = { error: (error as NodeJS.ErrnoException).code }; }
  }
  return result;
}
async function row(name: string, boundary: string, operation: () => Promise<void>) {
  const start = events.length;
  paths = [];
  let failure: unknown;
  try { await operation(); } catch (error) { failure = error; }
  const record = { name, boundary, result: failure ? "fail" : "pass", error: failure instanceof Error ? { name: failure.name, message: failure.message, stack: failure.stack } : failure, events: events.slice(start), witnesses: await witnesses() };
  rows.push(record);
  console.log(JSON.stringify({ name, boundary, result: record.result, error: record.error }));
}

await row("root/subpath constructors and declared capabilities agree", "public-package", async () => {
  assert.equal(RootWebDav, WebDavFileSystem);
  assert.match(import.meta.resolve("virtual-bash"), /\/consumer\/node_modules\/virtual-bash\/dist\/index.js$/);
  assert.match(import.meta.resolve("virtual-bash/fs/webdav"), /\/consumer\/node_modules\/virtual-bash\/dist\/fs\/webdav\/index.js$/);
  assert.equal(app.dav.capabilities.atomicRename, false);
});
for (const method of ["copyFile", "rename"] as const) {
  await row(`default ${method} preserves binary output using actual backing authority`, "public-positive", async () => {
    const { source, target } = await seed();
    await app.dav[method](source, target);
    assert.deepEqual(await app.native.readFile(target), payload);
    if (method === "rename") await assert.rejects(app.native.stat(source), isCode("ENOENT"));
    else assert.deepEqual(await app.native.readFile(source), payload);
    assert.doesNotMatch(await discovery(target), /<(?:[\w-]+:)?activelock[ >]/);
  });
  for (const answer of ["unknown", "same", "throw", "abort"] as const) {
    await row(`${method} ${answer} authority has no destructive request`, "public-authority", async () => {
      const { source, target } = await seed();
      const controller = new AbortController();
      const marker = new FsError("EACCES");
      let calls = 0;
      const filesystem = new WebDavFileSystem({ ...settings, compareEntry: async function () {
        assert.equal(this, filesystem); calls++;
        if (answer === "throw") throw marker;
        if (answer === "abort") { controller.abort(marker); return "distinct"; }
        return answer;
      } });
      const start = events.length;
      await assert.rejects(filesystem[method](source, target, { signal: controller.signal }));
      assert.equal(calls, 1);
      assert.ok(!events.slice(start).some(event => ["LOCK", "PUT", "COPY", "MOVE", "DELETE"].includes(event.method)));
      await unchanged(source, target);
    });
  }
