}
async function row(name: string, kind: "positive" | "guard", operation: () => Promise<void>) {
  const start = events.length;
  const priorPaths = new Set(paths);
  let detail: unknown;
  try { await operation(); }
  catch (error) { detail = { message: String(error), ...(error instanceof FsError ? { code: error.code, path: error.path } : {}) }; }
  const end = events.length;
  const lockWitnesses: { path: string; body?: string; error?: string }[] = [];
  for (const path of paths) if (!priorPaths.has(path)) {
    try { lockWitnesses.push({ path, body: await discovery(path) }); }
    catch (error) { lockWitnesses.push({ path, error: String(error) }); detail ??= { witnessError: String(error) }; }
  }
  const result = { name, kind, result: detail ? "fail" : "pass", ...(detail ? { detail } : {}), methods: events.slice(start, end).map(event => event.method), witnesses: await witnesses(), lockWitnesses };
  rows.push(result); await appendFile(`${evidence}/phase2-consumer.jsonl`, `${JSON.stringify(result)}\n`);
