import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { RealFileSystem, Shell, standardCommands, createMemoryFileSystem, createMountFileSystem } from "virtual-bash";
import type { FileStat, FileSystem, FsOptions, EntryComparison } from "virtual-bash";
import { WebDavFileSystem } from "virtual-bash/fs/webdav";
import type { WebDavFileSystemOptions } from "virtual-bash/fs/webdav";
import { createHttpsFetch, type WireObservation } from "./https.mjs";

export interface LiteralConfiguration {
  readonly baseUrl: string;
  readonly aliasUrl: string;
  readonly serverRoot: string;
  readonly caFile: string;
  readonly authorization: string;
}

export interface BackingLocation {
  readonly filesystem: RealFileSystem;
  readonly path: string;
}

function compareNative(left: FileStat, right: FileStat): EntryComparison {
  const valid = (stat: FileStat) => (typeof stat.identityScope === "symbol"
    || typeof stat.identityScope === "object" && stat.identityScope !== null)
    && Number.isSafeInteger(stat.dev) && stat.dev! >= 0
    && Number.isSafeInteger(stat.ino) && stat.ino! >= 0;
  if (!valid(left) || !valid(right) || left.identityScope !== right.identityScope) return "unknown";
  return left.dev === right.dev && left.ino === right.ino ? "same" : "distinct";
}

export async function createApplication(config: LiteralConfiguration, events: WireObservation[] = []) {
  const native = new RealFileSystem({ root: config.serverRoot });
  const mappings = new Map<FileSystem, RealFileSystem>([[native, native]]);
  const resolveBacking = async (filesystem: FileSystem, path: string, options: FsOptions): Promise<BackingLocation | undefined> => {
    options.signal?.throwIfAborted();
    const backing = mappings.get(filesystem);
    return backing ? { filesystem: backing, path } : undefined;
  };
  const compareEntry: NonNullable<WebDavFileSystemOptions["compareEntry"]> = async function(path, peer, peerPath, options = {}) {
    const own = await resolveBacking(this, path, options);
    const other = await resolveBacking(peer, peerPath, options);
    options.signal?.throwIfAborted();
    if (!own || !other) return "unknown";
    const left = await own.filesystem.stat(own.path, options);
    const right = await other.filesystem.stat(other.path, options);
    options.signal?.throwIfAborted();
    return compareNative(left, right);
  };
  const fetch = createHttpsFetch(new URL(config.baseUrl).origin, await readFile(config.caFile), events);
  const common = { fetch, headers: { Authorization: config.authorization }, timeoutMs: 5000, compareEntry };
  const dav = new WebDavFileSystem({ ...common, baseUrl: config.baseUrl });
  const alias = new WebDavFileSystem({ ...common, baseUrl: config.aliasUrl });
  const etag = new WebDavFileSystem({ ...common, baseUrl: config.baseUrl, overwritePolicy: "etag" });
  for (const filesystem of [dav, alias, etag]) mappings.set(filesystem, native);
  const mounted = createMountFileSystem({ root: createMemoryFileSystem(), mounts: { "/dav": dav, "/native": native, "/alias": alias } });
  const shell = new Shell({ fs: mounted }).use(standardCommands());
  return { dav, alias, etag, native, mounted, shell, fetch, resolveBacking };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const config: LiteralConfiguration = JSON.parse(await readFile(process.argv[2]!, "utf8"));
  const { shell } = await createApplication(config);
  const result = await shell.exec("printf 'hello WebDAV\\n' | cat > /dav/public-example.txt; cp /dav/public-example.txt /native/public-copy.txt; cat /dav/public-copy.txt");
  process.stdout.write(JSON.stringify(result));
  if (result.exitCode !== 0 || result.stdout !== "hello WebDAV\n") process.exitCode = 1;
}

import { request } from "node:https";
import { once } from "node:events";
import type { IncomingMessage } from "node:http";
import type { WebDavFetch } from "virtual-bash/fs/webdav";

export interface WireObservation {
  readonly url: string;
  readonly method: string;
  readonly requestHeaders: Readonly<Record<string, string>>;
  status?: number;
  responseHeaders?: Record<string, string>;
  uploadedBytes: number;
  downloadedBytes: number;
  pulls: number;
  drains: number;
  aborted: boolean;
  cancelled: boolean;
  ended: boolean;
}

export function createHttpsFetch(origin: string, certificate: Uint8Array, events: WireObservation[] = []): WebDavFetch {
  const allowed = new URL(origin);
  if (allowed.protocol !== "https:" || allowed.hostname !== "127.0.0.1" || allowed.username || allowed.password) {
    throw new Error("fixture transport requires explicit numeric loopback HTTPS");
  }
  const ca = Buffer.from(certificate);
  return async (url, init) => {
    const target = new URL(url);
    if (target.origin !== allowed.origin || target.username || target.password) throw new Error("unconfigured HTTPS origin");
    if (init.redirect !== "manual" || init.credentials !== "omit") throw new Error("explicit manual/omit policy required");
    const normalized = new Request(url, init);
    const requestHeaders = new Headers(normalized.headers);
    const originalBody = init.body;
    const knownLength = typeof originalBody === "string" ? Buffer.byteLength(originalBody)
      : ArrayBuffer.isView(originalBody) ? originalBody.byteLength
      : originalBody instanceof ArrayBuffer ? originalBody.byteLength
      : originalBody instanceof Blob ? originalBody.size
      : originalBody instanceof URLSearchParams ? Buffer.byteLength(originalBody.toString()) : undefined;
    if (knownLength !== undefined && !requestHeaders.has("content-length")) requestHeaders.set("content-length", String(knownLength));
    const signal = AbortSignal.any([normalized.signal, AbortSignal.timeout(10000)]);
    signal.throwIfAborted();
    const event: WireObservation = {
      url, method: normalized.method, requestHeaders: Object.fromEntries(requestHeaders),
      uploadedBytes: 0, downloadedBytes: 0, pulls: 0, drains: 0,
      aborted: false, cancelled: false, ended: false,
    };
    events.push(event);
    return new Promise<Response>((resolve, reject) => {
      let incoming: IncomingMessage | undefined;
      let bodyController: ReadableStreamDefaultController<Uint8Array> | undefined;
      const upload = normalized.body?.getReader();
      let finished = false;
      const cleanup = () => signal.removeEventListener("abort", abort);
      const fail = (reason: unknown) => {
        if (finished) return;
        finished = true;
        cleanup();
        reject(reason);
        bodyController?.error(reason);
        incoming?.destroy();
        outgoing.destroy(reason instanceof Error ? reason : new Error(String(reason)));
        void upload?.cancel(reason).catch(() => {});
      };
      const abort = () => { event.aborted = true; fail(signal.reason); };
      const outgoing = request(target, {
        method: normalized.method, headers: Object.fromEntries(requestHeaders),
        ca, rejectUnauthorized: true, agent: false,
      }, response => {
        incoming = response;
        const headers = new Headers();
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
          headers.append(response.rawHeaders[index]!, response.rawHeaders[index + 1]!);
        }
        event.status = response.statusCode!;
        event.responseHeaders = Object.fromEntries(headers);
        response.on("error", fail);
        const iterator = response[Symbol.asyncIterator]();
        const noBody = normalized.method === "HEAD" || [204, 205, 304].includes(response.statusCode!);
        const body = noBody ? null : new ReadableStream<Uint8Array>({
          start(controller) { bodyController = controller; },
          async pull(controller) {
            try {
              signal.throwIfAborted();
              event.pulls++;
              const item = await iterator.next();
              signal.throwIfAborted();
              if (item.done) {
                event.ended = true;
                finished = true;
                cleanup();
                controller.close();
              } else {
                const bytes = new Uint8Array(item.value as Uint8Array);
                event.downloadedBytes += bytes.byteLength;
                controller.enqueue(bytes);
              }
            } catch (error) { fail(error); }
          },
          cancel(reason) {
            event.cancelled = true;
            finished = true;
            cleanup();
            response.destroy();
            outgoing.destroy();
            void upload?.cancel(reason).catch(() => {});
            void iterator.return?.().catch(() => {});
          },
        }, { highWaterMark: 0 });
        if (noBody) {
          response.once("end", () => { event.ended = true; finished = true; cleanup(); });
          response.resume();
        }
        const result = new Response(body, { status: response.statusCode!, statusText: response.statusMessage ?? "", headers });
        Object.defineProperty(result, "url", { value: target.href });
        resolve(result);
      });
      outgoing.on("error", fail);
      signal.addEventListener("abort", abort, { once: true });
      if (signal.aborted) { abort(); return; }
      void (async () => {
        try {
          if (upload) {
            while (true) {
              signal.throwIfAborted();
              const item = await upload.read();
              if (item.done) break;
              const bytes = Buffer.from(item.value);
              event.uploadedBytes += bytes.length;
              if (!outgoing.write(bytes)) {
                event.drains++;
                await once(outgoing, "drain", { signal });
              }
            }
          }
          outgoing.end();
        } catch (error) { fail(error); }
        finally { upload?.releaseLock(); }
      })();
    });
  };
}

